const supersedeExecutionAuthorization = `-- name: SupersedeExecutionAuthorization :execrows
UPDATE worm_execution_authorizations
SET state = 'SUPERSEDED', ended_at = $1::timestamptz,
    end_reason_code = 'REAUTHORIZED', updated_at = $1::timestamptz
WHERE run_id = $2::uuid
  AND state = 'AUTHORIZED'
`

type SupersedeExecutionAuthorizationParams struct {
	Now   pgtype.Timestamptz
	RunID pgtype.UUID
}

func (q *Queries) SupersedeExecutionAuthorization(ctx context.Context, arg SupersedeExecutionAuthorizationParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeExecutionAuthorization, arg.Now, arg.RunID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

